export default JSON.parse("{\"schema\":\"ai-brain.semantic-merge.v1\",\"id\":\"ideas-for-practicing-describing-aac8ddbfe076\",\"title\":\"Ideas for Practicing Describing\",\"domain\":\"dbt\",\"relatedDomains\":[\"dbt\"],\"purpose\":\"handout\",\"capabilities\":[\"dbt\",\"reference\",\"research\"],\"similarityReview\":{\"threshold\":0.75,\"pairScores\":[0.976],\"method\":\"5-token shingle Jaccard within same explicit purpose/title context\"},\"provenance\":{\"mergePolicy\":\"shared structure/content consolidated; unique list items/fields retained; scalar conflicts retained as _merged_values\",\"sources\":[{\"sourcePath\":\"Unified_AI-Brain_PART_2_of_6/AI-Brain/json/therapy_dbt/02-dbt-mindfulness-mindfulness-handout-4b-ideas-for-practicing-describing-1584167f0a.json\",\"sha256\":\"1584167f0a2b0efd6da7831f035588040a61b3520139c8c9c549d2cb6c15e1ac\",\"domain\":\"dbt\",\"bytes\":6866},{\"sourcePath\":\"Unified_AI-Brain_PART_2_of_6/AI-Brain/json/therapy_dbt/mindfulness-handout-4b-ideas-for-practicing-describing-e457dc3240.json\",\"sha256\":\"e457dc324024fe3d31fe73b5327c556bcfe1c1123454fb305a86666132e47dab\",\"domain\":\"dbt\",\"bytes\":6741}]},\"data\":{\"pages\":[{\"pdf_page\":82,\"book_page\":\"58\",\"text\":\"58\\nMindfulness Handout 4b   (Mindfulness Worksheets 2\u20132c, 4\u20134b)\\nIdeas for Practicing Describing\\nPractice describing what you see outside of yourself:\\n  1.\\t\uf071\\tLie on the ground and watch the clouds in the sky. Find and describe cloud patterns that\\nyou see.\\n  2.\\t\uf071\\tSit on a bench on a busy street or at a park. Describe one thing about each person who\\nwalks by you.\\n  3.\\t\uf071\\tFind things in nature\u2014a leaf, a drop of water, a pet or other animal. Describe each thing in\\nas much detail as you can.\\n  4.\\t\uf071\\tDescribe as accurately as you can what a person has just said to you. Check to see if you\\nare correct.\\n  5.\\t\uf071\\tDescribe a person\u2019s face when the person seems angry, afraid, or sad. Notice and describe\\nthe shape, movement, and placement of the forehead, eyebrows, and eyes; the lips and\\nmouth; the cheeks; and so on.\\n  6.\\t\uf071\\tDescribe what a person has done or is doing now. Be very specific. Avoid describing\\nintentions or outcomes of the behavior that you do not directly observe. Avoid judgmental\\nlanguage.\\n  7.\\tOther:\\nPractice describing thoughts and feelings:\\n  8.\\t\uf071\\tDescribe your feelings as they arise within you: \u201cA feeling of anger is arising within me.\u201d\\n  9.\\t\uf071\\tDescribe your thoughts when you feel a strong emotion: \u201cI feel X, and my thoughts are Y.\u201d\\n10.\\t\uf071\\tDescribe your feelings after someone else does or says something: \u201cWhen you do X, I feel\\nY.\u201d\\n11.\\t \uf071\\tDescribe thoughts, feelings, and what you observed others do: \u201cWhen you do X, I feel Y,\\nand my thoughts are Z.\u201d \u201cWhen X occurs, I feel Y, and my thoughts are Z.\u201d\\n12.\\t\uf071\\tDescribe as many of your thoughts as you can while feeling a strong emotion.\\n13.\\tOther:\\nPractice describing your breathing:\\n14.\\t\uf071\\tEach time you inhale and exhale, as you inhale, be aware that \u201cI am inhaling, 1.\u201d When you\\nexhale, be aware that \u201cI am exhaling, 1.\u201d Remember to breathe from the stomach. When\\nbeginning the second inhalation, be aware that \u201cI am inhaling, 2.\u201d And, slowly exhaling, be\\naware that \u201cI am exhaling, 2.\u201d Continue on up through 10. After you have reached 10, return\\nto 1. Whenever you lose count, return to 1.\\n15.\\t\uf071\\tBegin to inhale gently and normally (from the stomach), describing in your mind that \u201cI\\nam inhaling normally.\u201d Exhale in awareness, \u201cI am exhaling normally.\u201d Continue for three\\nbreaths. On the fourth breath, extend the inhalation, describing in your mind that \u201cI am\\nbreathing in a long inhalation.\u201d Exhale in awareness, \u201cI am breathing out a long exhalation.\u201d\\nContinue for three breaths.\\n16.\\t\uf071\\tFollow the entrance and exit of air. Say to yourself, \u201cI am inhaling and following the\\ninhalation from its beginning to its end. I am exhaling and following the exhalation from its\\nbeginning to its end.\u201d\\n17.\\t Other:\"}],\"copyright_notice\":\"Extracted from user-provided PDF: DBT Skills Training Handouts and Worksheets, Second Edition by Marsha M. Linehan. Respect source copyright and purchaser-use limits.\",\"source_marker\":\"Mindfulness Handout 4b   (Mindfulness Worksheets 2\u20132c, 4\u20134b)\",\"source_pdf_pages\":[82],\"fillable_html_created\":false,\"created_at\":\"2026-06-25T17:33:54\",\"json_path\":\"json/items/mindfulness/handouts/mindfulness_handout_4b_ideas_for_practicing_describing.json\",\"item_number\":\"4b\",\"full_text\":\"Mindfulness Handout 4b   (Mindfulness Worksheets 2\u20132c, 4\u20134b)\\nIdeas for Practicing Describing\\nPractice describing what you see outside of yourself:\\n  1.\\t\uf071\\tLie on the ground and watch the clouds in the sky. Find and describe cloud patterns that\\nyou see.\\n  2.\\t\uf071\\tSit on a bench on a busy street or at a park. Describe one thing about each person who\\nwalks by you.\\n  3.\\t\uf071\\tFind things in nature\u2014a leaf, a drop of water, a pet or other animal. Describe each thing in\\nas much detail as you can.\\n  4.\\t\uf071\\tDescribe as accurately as you can what a person has just said to you. Check to see if you\\nare correct.\\n  5.\\t\uf071\\tDescribe a person\u2019s face when the person seems angry, afraid, or sad. Notice and describe\\nthe shape, movement, and placement of the forehead, eyebrows, and eyes; the lips and\\nmouth; the cheeks; and so on.\\n  6.\\t\uf071\\tDescribe what a person has done or is doing now. Be very specific. Avoid describing\\nintentions or outcomes of the behavior that you do not directly observe. Avoid judgmental\\nlanguage.\\n  7.\\tOther:\\nPractice describing thoughts and feelings:\\n  8.\\t\uf071\\tDescribe your feelings as they arise within you: \u201cA feeling of anger is arising within me.\u201d\\n  9.\\t\uf071\\tDescribe your thoughts when you feel a strong emotion: \u201cI feel X, and my thoughts are Y.\u201d\\n10.\\t\uf071\\tDescribe your feelings after someone else does or says something: \u201cWhen you do X, I feel\\nY.\u201d\\n11.\\t \uf071\\tDescribe thoughts, feelings, and what you observed others do: \u201cWhen you do X, I feel Y,\\nand my thoughts are Z.\u201d \u201cWhen X occurs, I feel Y, and my thoughts are Z.\u201d\\n12.\\t\uf071\\tDescribe as many of your thoughts as you can while feeling a strong emotion.\\n13.\\tOther:\\nPractice describing your breathing:\\n14.\\t\uf071\\tEach time you inhale and exhale, as you inhale, be aware that \u201cI am inhaling, 1.\u201d When you\\nexhale, be aware that \u201cI am exhaling, 1.\u201d Remember to breathe from the stomach. When\\nbeginning the second inhalation, be aware that \u201cI am inhaling, 2.\u201d And, slowly exhaling, be\\naware that \u201cI am exhaling, 2.\u201d Continue on up through 10. After you have reached 10, return\\nto 1. Whenever you lose count, return to 1.\\n15.\\t\uf071\\tBegin to inhale gently and normally (from the stomach), describing in your mind that \u201cI\\nam inhaling normally.\u201d Exhale in awareness, \u201cI am exhaling normally.\u201d Continue for three\\nbreaths. On the fourth breath, extend the inhalation, describing in your mind that \u201cI am\\nbreathing in a long inhalation.\u201d Exhale in awareness, \u201cI am breathing out a long exhalation.\u201d\\nContinue for three breaths.\\n16.\\t\uf071\\tFollow the entrance and exit of air. Say to yourself, \u201cI am inhaling and following the\\ninhalation from its beginning to its end. I am exhaling and following the exhalation from its\\nbeginning to its end.\u201d\\n17.\\t Other:\",\"source_pdf\":\"DBT Skills Workbook.pdf\",\"related_references\":[\"Mindfulness Worksheets 2\u20132c, 4\u20134b\"],\"id\":\"mindfulness_handout_4b\",\"item_type\":\"handout\",\"is_example\":false,\"source_book_pages\":[\"58\"],\"title\":\"Ideas for Practicing Describing\",\"module_category\":\"Mindfulness Skills\",\"shared_json_path\":\"shared/02_dbt_mindfulness/handouts_json/mindfulness_handout_4b_ideas_for_practicing_describing.json\",\"module\":\"Mindfulness\",\"keywords\":[\"Describing\",\"Ideas\",\"Practicing\"]}}");
